define class Point as pub val int x = 5; pub val int y = 8; end
fnc total(Point {x,y}): int { return x+y; }
pub routine main(): void { stdio.stdout.write(total(new Point())); return; }

define class Point as pub val int x = 5; pub val int y = 8; end
define class Calc as pub total(Point {x,y}): int { return x+y; } end
pub routine main(): void { stdio.stdout.write(new Calc().total(new Point())); return; }

